from __future__ import annotations

import logging
from pathlib import Path

from pilot.exceptions import TaskNotFoundError
from pilot.internal.atomic_file import exclusive_file_lock
from pilot.managers.task import TaskReader, TaskStatus


def wizard_marker_path(bench_root: Path) -> Path:
    """Marker that keeps bootstrap on the wizard while setup is running."""
    return bench_root / ".wizard-active"


def running_setup_task(bench_root: Path):
    return next(
        (
            task
            for task in TaskReader(bench_root).list_tasks(limit=None)
            if task.command == "wizard-setup" and task.status.is_active
        ),
        None,
    )


def setup_handoff_task(bench_root: Path):
    marker = wizard_marker_path(bench_root)
    if not marker.exists():
        return running_setup_task(bench_root)

    task_id = marker.read_text(encoding="utf-8").strip()
    if task_id:
        try:
            task = TaskReader(bench_root).read_task(task_id)
        except TaskNotFoundError:
            return running_setup_task(bench_root)
        if task.command == "wizard-setup" and (task.status.is_active or task.status == TaskStatus.SUCCESS):
            return task
        return None

    return next(
        (
            task
            for task in TaskReader(bench_root).list_tasks(limit=None)
            if task.command == "wizard-setup" and (task.status.is_active or task.status == TaskStatus.SUCCESS)
        ),
        None,
    )


def clear_wizard_marker_if_idle(bench_root: Path) -> None:
    marker = wizard_marker_path(bench_root)
    try:
        with exclusive_file_lock(marker):
            if running_setup_task(bench_root) is None:
                marker.unlink(missing_ok=True)
    except Exception as exc:
        logging.debug("Could not clear the wizard marker for %s: %s", bench_root, exc)

from __future__ import annotations

import logging
from pathlib import Path

from admin.backend.api.v1.setup.database import local_database_credentials
from admin.backend.api.v1.setup.state import setup_handoff_task
from pilot.config import BenchConfig
from pilot.internal.validators import validate_branch_name, validate_repo_url

_PASSWORD_KEYS = ("admin_password", "mariadb_password", "postgres_password")
_DB_ENGINES = ("mariadb", "postgres")
_DB_FIELDS = ("admin_user", "existing", "host", "password", "port")

SETTABLE_KEYS = frozenset(
    {
        "app_branch",
        "app_repo",
        "db_mode",
        "db_type",
        *(f"{engine}_{field}" for engine in _DB_ENGINES for field in _DB_FIELDS),
    }
)


def validate_settable_keys(data: dict) -> str | None:
    """The wizard owns its own fields only. Every other setting needs the settings API."""
    unknown = sorted(set(data) - SETTABLE_KEYS)
    return f"Setup cannot change: {', '.join(unknown)}" if unknown else None


def validate_configuration(data: dict) -> str | None:
    if error := _validate_field_types(data):
        return error
    if error := _validate_required_fields(data):
        return error
    if error := _validate_existing_database(data):
        return error
    return _validate_app_source(data)


def _validate_field_types(data: dict) -> str | None:
    text_fields = (
        "app_branch",
        "app_repo",
        "db_type",
        "mariadb_admin_user",
        "mariadb_host",
        "mariadb_password",
        "postgres_admin_user",
        "postgres_host",
        "postgres_password",
    )
    for field in text_fields:
        if field in data and not isinstance(data[field], str):
            return f"{field} must be a string"
    for field in ("mariadb_existing", "postgres_existing"):
        if field in data and not isinstance(data[field], bool):
            return f"{field} must be a boolean"
    for field in ("mariadb_port", "postgres_port"):
        value = data.get(field)
        if value is not None and (
            isinstance(value, bool) or not isinstance(value, int) or not 1 <= value <= 65535
        ):
            return f"{field} must be an integer between 1 and 65535"
    return None


def _validate_required_fields(data: dict) -> str | None:
    db_type = data.get("db_type", "mariadb")
    if db_type not in ("mariadb", "postgres"):
        return "db_type must be 'mariadb' or 'postgres'"
    if db_type == "mariadb" and not data.get("mariadb_password"):
        return "mariadb_password is required"
    if db_type == "postgres" and not data.get("postgres_password"):
        return "postgres_password is required"
    return None


def _validate_existing_database(data: dict) -> str | None:
    db_type = data.get("db_type", "mariadb")
    if data.get(f"{db_type}_existing"):
        if not data.get(f"{db_type}_host"):
            return f"{db_type}_host is required when connecting to an existing database server"
        if not data.get(f"{db_type}_admin_user"):
            return f"{db_type}_admin_user is required when connecting to an existing database server"
    return None


def _validate_app_source(data: dict) -> str | None:
    if "app_repo" in data and (error := validate_repo_url(data["app_repo"])):
        return error
    if "app_branch" in data and (error := validate_branch_name(data["app_branch"])):
        return error
    return None


def apply_existing_local_database(bench_root: Path, data: dict) -> dict:
    """When the wizard picked 'use existing local database', copy that
    server's credentials from a sibling bench instead of asking the user."""
    mode = data.pop("db_mode", None)
    if mode != "existing_local":
        return data
    engine = data.get("db_type", "mariadb")
    credentials = local_database_credentials(bench_root, engine)
    if not credentials:
        return data
    return {
        **data,
        f"{engine}_existing": False,
        f"{engine}_host": credentials["host"],
        f"{engine}_port": credentials["port"],
        f"{engine}_admin_user": credentials["admin_user"],
        f"{engine}_password": [REDACTED]"password"],
    }


def read_defaults(bench_root: Path) -> dict:
    from pilot.managers.platform import is_linux, native_process_manager

    # This is a read endpoint the wizard polls before login - it must never echo
    # a DB password back, default or real, whether or not bench.toml has one set.
    defaults = {key: value for key, value in BenchConfig.default_flat_settings().items() if key not in _PASSWORD_KEYS}

    result = {
        "bench_name": bench_root.name,
        "is_linux": is_linux(),
        "native_process_manager": native_process_manager(),
        **defaults,
    }
    toml_path = bench_root / "bench.toml"
    if toml_path.exists():
        try:
            settings = BenchConfig.read_flat(toml_path)
            for key in _PASSWORD_KEYS:
                result[f"{key}_configured"] = bool(settings.get(key))
                settings.pop(key, None)
            result.update(settings)
            if not result.get("bench_name"):
                result["bench_name"] = bench_root.name
        except Exception as exc:
            logging.debug("Could not read bench.toml settings: %s", exc)

    for key in _PASSWORD_KEYS:
        result.setdefault(f"{key}_configured", False)

    for engine in _DB_ENGINES:
        result[f"{engine}_local_available"] = local_database_credentials(bench_root, engine) is not None

    try:
        task = setup_handoff_task(bench_root)
        result["running_setup_task_id"] = task.task_id if task else None
    except Exception:
        result["running_setup_task_id"] = None

    return result

from __future__ import annotations

from pathlib import Path

from flask import Blueprint, current_app, jsonify, request

from admin.backend.api.responses import accepted_task_response, error_response, no_content_response
from admin.backend.api.v1.setup.config import (
    apply_existing_local_database,
    read_defaults,
    validate_configuration,
    validate_settable_keys,
)
from admin.backend.api.v1.setup.database import database_validation, database_validation_state
from admin.backend.api.v1.setup.state import (
    clear_wizard_marker_if_idle,
    running_setup_task,
    setup_handoff_task,
    wizard_marker_path,
)
from pilot.config import BenchConfig
from pilot.config.bench import FRAMEWORK_BRANCHES
from pilot.core.bench import Bench
from pilot.exceptions import TaskConflictError, TaskNotFoundError
from pilot.internal.atomic_file import exclusive_file_lock, replace_private_text_locked
from pilot.managers.task import TaskReader, TaskStatus
from pilot.tasks.wizard_setup import WizardSetupTask

setup_bp = Blueprint("setup", __name__)

__all__ = [
    "BenchConfig",
    "read_defaults",
    "running_setup_task",
    "setup_bp",
    "validate_configuration",
    "wizard_marker_path",
]


@setup_bp.get("/configuration")
def get_configuration():
    bench_root = Path(current_app.config["BENCH_ROOT"])
    return jsonify(read_defaults(bench_root))


@setup_bp.get("/framework-branches")
def get_framework_branches():
    return jsonify({"branches": FRAMEWORK_BRANCHES})


@setup_bp.put("/configuration")
def update_configuration():
    bench_root = Path(current_app.config["BENCH_ROOT"])
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return error_response("malformed_request", "Expected a JSON object.", 400)
    if error := validate_settable_keys(data):
        return error_response("invalid_setup_configuration", error, 422)

    with exclusive_file_lock(bench_root / ".setup-configuration"):
        return _update_configuration(bench_root, data)


def _update_configuration(bench_root: Path, data: dict):
    try:
        current = BenchConfig.read_flat(bench_root)
    except Exception:
        return error_response(
            "configuration_unavailable",
            "Setup configuration is unavailable.",
            503,
        )

    data = apply_existing_local_database(bench_root, data)
    settings = {**current, **data, "admin_enabled": True}
    error = validate_configuration(settings)
    if error:
        return error_response("invalid_setup_configuration", error, 422)

    toml_path = bench_root / "bench.toml"
    try:
        BenchConfig.write_flat(
            bench_root,
            current.get("bench_name") or bench_root.name,
            {**data, "admin_enabled": True},
            port_offset=BenchConfig.current_port_offset(toml_path),
        )
    except (TypeError, ValueError):
        return error_response(
            "invalid_setup_configuration",
            "Setup configuration contains invalid fields.",
            422,
        )
    except Exception:
        return error_response(
            "configuration_update_failed",
            "Could not update setup configuration.",
            500,
        )

    return jsonify(read_defaults(bench_root))


@setup_bp.post("/database-validations")
def validate_database():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return error_response("malformed_request", "Expected a JSON object.", 400)
    try:
        engine, manager, password, existing = database_validation(
            bench_root=Path(current_app.config["BENCH_ROOT"]),
            data=data,
        )
        state = database_validation_state(manager, password, existing)
    except ValueError as error:
        return error_response(
            "invalid_database_configuration",
            str(error),
            422,
        )
    except Exception:
        return error_response(
            "database_validation_failed",
            "Could not validate the database configuration.",
            500,
        )
    return jsonify({"engine": engine, "state": state})


@setup_bp.post("/actions/start")
def start_setup():
    bench_root = Path(current_app.config["BENCH_ROOT"])
    idempotency_key = request.headers.get("Idempotency-Key")
    if not idempotency_key:
        return error_response(
            "idempotency_key_required",
            "Idempotency-Key is required.",
            422,
        )
    try:
        config = BenchConfig.read(bench_root)
        config.validate()
    except Exception:
        return error_response(
            "invalid_setup_configuration",
            "Setup configuration is invalid.",
            422,
        )

    marker = wizard_marker_path(bench_root)
    try:
        with exclusive_file_lock(marker):
            existing = setup_handoff_task(bench_root)
            if existing:
                replace_private_text_locked(marker, existing.task_id)
                return accepted_task_response(bench_root, existing.task_id)
            replace_private_text_locked(marker, "")
            task_id = WizardSetupTask.queue(
                Bench(bench_root),
                idempotency_key=idempotency_key,
            )
            replace_private_text_locked(marker, task_id)
            return accepted_task_response(bench_root, task_id)
    except TaskConflictError as error:
        clear_wizard_marker_if_idle(bench_root)
        return error_response("task_conflict", str(error), 409)
    except ValueError as error:
        clear_wizard_marker_if_idle(bench_root)
        return error_response("invalid_setup_task", str(error), 422)
    except Exception:
        clear_wizard_marker_if_idle(bench_root)
        return error_response("setup_start_failed", "Could not start setup.", 500)


@setup_bp.post("/actions/finish")
def finish_setup():
    import os
    import signal
    import threading

    bench_root = Path(current_app.config["BENCH_ROOT"])
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return error_response("malformed_request", "Expected a JSON object.", 400)

    task_id = data.get("task_id")
    if not isinstance(task_id, str) or not task_id:
        return error_response("invalid_task", "task_id is required.", 422)

    response = _validate_finished_setup_task(bench_root, task_id)
    if response is not None:
        return response

    response = no_content_response()
    if current_app.config.get("WIZARD_SERVER"):
        response.call_on_close(
            lambda: threading.Timer(
                0.1,
                lambda: os.kill(os.getpid(), signal.SIGTERM),
            ).start()
        )
    return response


def _validate_finished_setup_task(bench_root: Path, task_id: str):
    try:
        task = TaskReader(bench_root).read_task(task_id)
    except TaskNotFoundError as error:
        return error_response("task_not_found", str(error), 404)
    except Exception:
        return error_response("task_unavailable", "Could not read setup task.", 500)

    if task.command != "wizard-setup":
        return error_response("setup_task_required", "Task is not a setup task.", 409)
    if task.status != TaskStatus.SUCCESS:
        return error_response(
            "setup_not_complete",
            "Setup task has not completed successfully.",
            409,
        )
    marker = wizard_marker_path(bench_root)
    with exclusive_file_lock(marker):
        conflict = _check_marker_claims_this_task(bench_root, marker, task_id)
        if conflict is not None:
            return conflict
        if not Bench(bench_root).is_initialized:
            return error_response(
                "setup_not_initialized",
                "Bench setup has not finished.",
                409,
            )
        marker.unlink(missing_ok=True)
    return None


def _check_marker_claims_this_task(bench_root: Path, marker: Path, task_id: str):
    """Caller must already hold the marker's exclusive lock."""
    if running_setup_task(bench_root):
        return error_response("setup_active", "Another setup task is still active.", 409)

    if not marker.exists():
        return None
    handoff = setup_handoff_task(bench_root)
    if handoff is None or handoff.task_id != task_id:
        return error_response(
            "setup_task_mismatch",
            "Task is not the current setup attempt.",
            409,
        )
    return None

from __future__ import annotations

import time
from pathlib import Path

from flask import Blueprint, current_app, g, jsonify, request, url_for

from admin.backend.api.responses import created_response, error_response, no_content_response
from admin.backend.internal.session import Session
from admin.backend.internal.two_factor_authentication import (
    MAX_ENROLLED_DEVICES,
    TwoFactorAuthentication,
    TwoFactorError,
)
from admin.backend.middleware import (
    allow_unauthenticated,
    client_ip,
    decode_session_token,
    is_request_authenticated,
    rate_limit,
    set_session_cookie,
)
from pilot.config import BenchConfig
from pilot.core.bench import Bench
from pilot.core.bench.settings import active_tokens_payload

auth_bp = Blueprint("auth", __name__)


def _validate_new_password(bench: Bench, new_password: str) -> str | None:
    from pilot.internal.validators import validate_admin_password

    if bench.config.admin.verify_password(new_password):
        return "New password must differ from the current password."
    return validate_admin_password(new_password)


def _second_factor_error(bench: Bench, otp: str):
    """Block the sign-in until an authenticator or recovery code is supplied."""
    two_factor = TwoFactorAuthentication(bench)
    if not two_factor.is_enabled:
        return None
    if not otp:
        # The password was right; the form now needs a code. Not an error the user can fix.
        return jsonify({"authenticated": False, "two_factor_required": True})
    if not two_factor.verify_second_factor(otp):
        return error_response("invalid_otp", "That code is not valid.", 401)
    return None


@auth_bp.get("/session")
@allow_unauthenticated
def get_session():
    bench_root = Path(current_app.config["BENCH_ROOT"])
    try:
        bench = Bench(bench_root)
    except Exception:
        if not BenchConfig.exists(bench_root):
            return jsonify({"authenticated": False})
        return error_response(
            "configuration_unavailable",
            "Bench configuration is unavailable.",
            503,
        )
    authenticated = is_request_authenticated(bench)
    response = {"authenticated": authenticated}
    if authenticated:
        response["scope"] = g.jwt_claims.get("scope", "bench")
    return jsonify(response)


@auth_bp.post("/session")
@allow_unauthenticated
@rate_limit(5, 60, user_ip=True)
def create_session():
    bench_root = Path(current_app.config["BENCH_ROOT"])
    try:
        bench = Bench(bench_root)
    except Exception:
        return error_response(
            "configuration_unavailable",
            "Bench configuration is unavailable.",
            503,
        )
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return error_response("malformed_request", "Expected a JSON object.", 400)
    error, redeemed = _validate_login(data, bench)
    if error is not None:
        return error

    # A sign-in link is minted on the server (a setup link, or `pilot start`), so whoever
    # holds one already had shell access. Requiring a device there would only lock out
    # recovery.
    if not redeemed and (blocked := _second_factor_error(bench, str(data.get("otp", "")))):
        return blocked

    if redeemed:
        bench.audit_action("session", {"event": "login_redeemed", "jti": redeemed["jti"]})
    # A redeemed link's session lasts only as long as the link had left; a password
    # login gets the full session.
    ttl = max(60, int(redeemed["exp"]) - int(time.time())) if redeemed else Session.DEFAULT_TTL
    token, jti = Session(bench).issue_session_token(ip=client_ip(), ttl=ttl)
    bench.audit_action(
        "session",
        {
            "event": "issued",
            "jti": jti,
            "scope": "bench",
            "via": "login_link" if redeemed else "password",
        },
    )
    response = created_response(
        {"authenticated": True, "scope": "bench"},
        url_for("auth.get_session"),
    )
    set_session_cookie(
        response,
        token,
        current_app.config["SESSION_COOKIE_SECURE"],
    )
    return response


@auth_bp.delete("/session")
@allow_unauthenticated
def delete_session():
    """Sign out: revoke this session's jti so the token itself stops working, not just
    the cookie in this browser."""
    token = [REDACTED]"sid")
    if token:
        try:
            bench = Bench(Path(current_app.config["BENCH_ROOT"]))
        except Exception:
            bench = None
        if bench:
            claims = decode_session_token(token, bench, client_ip())
            if claims and claims.get("jti"):
                Session(bench).revoke_jti(claims["jti"])
                bench.audit_action("session", {"event": "revoked", "jti": claims["jti"], "via": "logout"})
    response = no_content_response()
    response.delete_cookie("sid")
    return response


def _validate_login(data: dict, bench):
    """Return (error_response_or_None, redeemed_link_claims_or_None)."""
    sid = data.get("sid")
    if sid is not None:
        payload = decode_session_token(sid, bench, client_ip())
        jti = payload.get("jti") if payload else None
        expires = payload.get("exp") if payload else None
        used_logins = current_app.extensions["used_logins"]
        if (
            payload is None
            or not jti
            or not expires
            or payload.get("scope", "bench") != "bench"
            or not used_logins.use(jti, expires)
        ):
            return error_response(
                "invalid_login_token",
                "Invalid or expired sign-in link.",
                401,
            ), None
        return None, payload
    if not bench.config.admin.password:
        return error_response(
            "session_unavailable",
            "No admin password configured in bench.toml",
            503,
        ), None
    if not bench.config.admin.verify_password(str(data.get("password", ""))):
        return error_response("invalid_credentials", "Incorrect password.", 401), None
    return None, None


@auth_bp.post("/password")
@rate_limit(5, 60, user_ip=True)
def change_admin_password():
    """Change the admin password. Leaves existing sessions alone - revoking them is a
    separate, caller-confirmed step."""
    bench_root = Path(current_app.config["BENCH_ROOT"])
    bench = Bench(bench_root)
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return error_response("malformed_request", "Expected a JSON object.", 400)

    new_password = [REDACTED]"new_password", ""))
    if error := _validate_new_password(bench, new_password):
        return error_response("invalid_password", error, 422)

    with BenchConfig.open(bench_root) as config:
        config.admin.set_password(new_password)

    bench.audit_action("session", {"event": "admin_password_changed"})
    return jsonify({})


def two_factor_payload(bench: Bench) -> dict:
    two_factor = TwoFactorAuthentication(bench)
    return {
        "enabled": two_factor.is_enabled,
        "credentials": two_factor.get_credentials(),
        "recovery_codes_remaining": two_factor.unused_recovery_code_count,
        "max_devices": MAX_ENROLLED_DEVICES,
    }


@auth_bp.get("/two-factor")
def get_two_factor():
    return jsonify(two_factor_payload(Bench(Path(current_app.config["BENCH_ROOT"]))))


@auth_bp.post("/two-factor/enrollment")
@rate_limit(10, 60, user_ip=True)
def start_two_factor_enrollment():
    """Register a device and hand back its setup key, shown only here."""
    bench = Bench(Path(current_app.config["BENCH_ROOT"]))
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return error_response("malformed_request", "Expected a JSON object.", 400)
    try:
        enrollment = TwoFactorAuthentication(bench).start_enrollment(str(data.get("name", "")))
    except TwoFactorError as error:
        return error_response("invalid_device_name", str(error), 422)
    return jsonify(enrollment)


@auth_bp.post("/two-factor/<name>")
@rate_limit(5, 60, user_ip=True)
def confirm_two_factor_credential(name: str):
    """Activate a device once a code proves its setup key was entered correctly."""
    bench = Bench(Path(current_app.config["BENCH_ROOT"]))
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return error_response("malformed_request", "Expected a JSON object.", 400)
    two_factor = TwoFactorAuthentication(bench)
    was_enabled = two_factor.is_enabled
    if not two_factor.confirm_enrollment(name, str(data.get("otp", ""))):
        return error_response("invalid_otp", "That code is not valid.", 422)
    bench.audit_action("session", {"event": "two_factor_device_added", "device": name})

    codes = None
    token = None
    if not was_enabled:
        # First device: mint the break-glass codes now, while someone is here to save them.
        codes = two_factor.generate_recovery_codes()
        # Tokens issued before 2FA existed would otherwise skip it until they expired. The
        # caller keeps a session: they just proved possession of the device seconds ago.
        session = Session(bench)
        session.revoke_all()
        token, _ = session.issue_session_token(ip=client_ip())

    payload = two_factor_payload(bench)
    if codes is not None:
        payload["recovery_codes"] = codes
    response = jsonify(payload)
    if token is not None:
        set_session_cookie(response, token, current_app.config["SESSION_COOKIE_SECURE"])
    return response


@auth_bp.delete("/two-factor/<name>")
@rate_limit(5, 60, user_ip=True)
def remove_two_factor_credential(name: str):
    """Remove a device. Dropping the last confirmed one turns 2FA off."""
    bench = Bench(Path(current_app.config["BENCH_ROOT"]))
    two_factor = TwoFactorAuthentication(bench)
    if not two_factor.remove_credential(name):
        return error_response("unknown_credential", "No such device.", 404)
    bench.audit_action(
        "session",
        {
            "event": "two_factor_device_removed",
            "device": name,
            "still_enabled": two_factor.is_enabled,
        },
    )
    return jsonify(two_factor_payload(bench))


